"""Prepare only the FB environment for Nov26; no allocation or publication."""
import ast,base64,hashlib,json,os,subprocess,sys,zlib
from pathlib import Path
FINGERPRINT='16e9b5c17e19d40a62fda15b18f8e4ab622d055a586ff314debe0d0f82fcc452'
ADDITIONS={n:base64.b64decode(b) for n,b in json.loads(zlib.decompress(base64.b64decode(''))).items()}

def safe(path):
    for item in (path,*path.parents):
        if (item.exists() or item.is_symlink()) and (item.is_symlink() or bool(getattr(item.lstat(),'st_file_attributes',0)&0x400)):raise ValueError('目录包含链接，未安装或删除素材。')
    return path

def install(root):
    root=safe(Path(root).absolute()).resolve()
    if not safe(root/'upload_config.json').is_file() or not safe(root/'.venv/Scripts/python.exe').is_file():raise ValueError('请在原FB上传电脑运行，配置或Python缺失。')
    manifest={n:hashlib.sha256(b).hexdigest() for n,b in ADDITIONS.items()}
    if hashlib.sha256(json.dumps(manifest,sort_keys=True).encode()).hexdigest()!=FINGERPRINT:raise ValueError('工具包指纹异常，未运行。')
    for n,b in ADDITIONS.items():
        if Path(n).name!=n:raise ValueError('工具文件名异常。')
        if n.endswith('.py'):ast.parse(b.decode('utf-8-sig'))
    folder=root/'material-staging/tools'/('nov26-prepare-'+FINGERPRINT[:16])
    safe(folder);folder.mkdir(parents=True,exist_ok=True);safe(root/'logs').mkdir(exist_ok=True)
    content=dict(ADDITIONS,**{'runtime-sha256.json':json.dumps(manifest,sort_keys=True).encode()})
    for name,data in content.items():
        path=safe(folder/name)
        if path.exists():
            if path.read_bytes()!=data:raise ValueError('已有不可变工具文件变化，未覆盖：'+name)
        else:
            with path.open('xb') as f:f.write(data);f.flush();os.fsync(f.fileno())
    for n,sha in manifest.items():
        if hashlib.sha256(safe(folder/n).read_bytes()).hexdigest()!=sha:raise ValueError('缓存指纹异常。')
    return root,folder

VERIFY="import sys;from pathlib import Path;sys.path.insert(0,sys.argv[2]);sys.path.insert(0,sys.argv[1]);import prepare_fb_for_nov26_20261126 as p;assert p.DAY=='2026-11-26' and p.CUTOFF=='2026-11-25';assert {'ig-autoupload','instagram'}<=p.cleanup.PROTECTED;assert p.disabled.ACCOUNTS=={'fb32','fb52'};assert all(r['material_date']<='2026-11-25' for r in p.known_entries());print('VERIFIED: FB cleanup through Nov25; Instagram preserved; no new publication',flush=True)"

def start(root):
    if sys.platform!='win32':raise ValueError('请在原Windows上传电脑运行。')
    root,folder=install(root)
    subprocess.run([sys.executable,'-c',VERIFY,str(folder),str(root)],check=True,cwd=root)
    # A real script process preserves the verifiable bootstrap/venv parent chain.
    return subprocess.run([sys.executable,'-u',str(folder/'prepare_fb_for_nov26_20261126.py'),str(root)],cwd=root).returncode

if __name__=='__main__':
    sys.stdout.reconfigure(encoding='utf-8',line_buffering=True)
    try:raise SystemExit(start(Path(sys.argv[1])))
    except Exception as error:print('STOP：'+(str(error) or type(error).__name__),flush=True);raise SystemExit(1)
